using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using SchoolERP.Domain.Entities;namespace SchoolERP.Infrastructure.Persistence.Configurations;public sealed class SubjectConfiguration:IEntityTypeConfiguration<Subject>{public void Configure(EntityTypeBuilder<Subject>b){b.HasAlternateKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId,x.Id}).HasName("ak_subjects_tenant_school_year_id");b.ToTable("subjects",t=>{t.HasCheckConstraint("ck_subjects_order","display_order >= 0");t.HasCheckConstraint("ck_subjects_credits","credit_hours IS NULL OR (credit_hours > 0 AND credit_hours <= 100)");t.HasCheckConstraint("ck_subjects_periods","weekly_periods IS NULL OR (weekly_periods BETWEEN 1 AND 50)");t.HasCheckConstraint("ck_subjects_status","status BETWEEN 1 AND 4");});b.ConfigureAudit();b.Property(x=>x.TenantId).HasColumnName("tenant_id");b.Property(x=>x.SchoolId).HasColumnName("school_id");b.Property(x=>x.AcademicYearId).HasColumnName("academic_year_id");b.Property(x=>x.Name).HasColumnName("name").HasMaxLength(150).IsRequired();b.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50).IsRequired();b.Property(x=>x.ShortName).HasColumnName("short_name").HasMaxLength(50);b.Property(x=>x.Type).HasColumnName("type").HasConversion<int>();b.Property(x=>x.Category).HasColumnName("category").HasConversion<int>();b.Property(x=>x.DisplayOrder).HasColumnName("display_order");b.Property(x=>x.CreditHours).HasColumnName("credit_hours").HasPrecision(5,2);b.Property(x=>x.WeeklyPeriods).HasColumnName("weekly_periods");b.Property(x=>x.Status).HasColumnName("status").HasConversion<int>();b.Property(x=>x.Description).HasColumnName("description").HasMaxLength(1000);b.Property(x=>x.ActivatedAt).HasColumnName("activated_at");b.Property(x=>x.DeactivatedAt).HasColumnName("deactivated_at");b.Property(x=>x.ArchivedAt).HasColumnName("archived_at");b.HasOne(x=>x.Tenant).WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.School).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.AcademicYear).WithMany().HasForeignKey(x=>new{x.TenantId,x.SchoolId,x.AcademicYearId}).HasPrincipalKey(x=>new{x.TenantId,x.SchoolId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.TenantId);b.HasIndex(x=>x.SchoolId);b.HasIndex(x=>x.AcademicYearId);b.HasIndex(x=>new{x.SchoolId,x.AcademicYearId,x.Code}).IsUnique().HasDatabaseName("ux_subjects_school_year_code");b.HasIndex(x=>new{x.SchoolId,x.AcademicYearId,x.Status});b.HasIndex(x=>new{x.SchoolId,x.AcademicYearId,x.DisplayOrder});}}
